import{_ as s,o as a,c as i,ao as e}from"./chunks/framework.CFcQhfmq.js";const g=JSON.parse('{"title":"Data dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"visualisation/dashboard.md","filePath":"visualisation/dashboard.md","lastUpdated":null}'),n={name:"visualisation/dashboard.md"};function l(h,t,d,p,r,o){return a(),i("div",null,[...t[0]||(t[0]=[e(`<h1 id="Data-dashboard" tabindex="-1">Data dashboard <a class="header-anchor" href="#Data-dashboard" aria-label="Permalink to &quot;Data dashboard {#Data-dashboard}&quot;">​</a></h1><p>The dashboard pages through the sites of a ModEM data file, one site at a time, and masks data. It is the place to clean field data before an inversion, and to look at the fit after one. The mask is saved as a text file that applies to the EDIs or to any ModEM file of the same survey.</p><h2 id="Open-it" tabindex="-1">Open it <a class="header-anchor" href="#Open-it" aria-label="Permalink to &quot;Open it {#Open-it}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MTGeophysics</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">DataDashboard</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data.dat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)                              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># observed only</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">DataDashboard</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data.dat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; predicted </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;dpred.dat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># observed against a ModEM response</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">DataDashboard</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data.dat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; mask </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;data_mask.txt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># continue from a saved mask</span></span></code></pre></div><p>EDI files are converted to a ModEM file first (see <a href="/MTGeophysics.jl/previews/PR50/data/files#EDI-files">EDI files</a>):</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">DataDashboard</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">EDIToModEM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;EDI/COPROD2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))               </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># writes EDI/COPROD2.dat</span></span></code></pre></div><p>From the command line, with a directory of EDIs or a ModEM file:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/edit_data.jl</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">data.dat</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> edi_dir</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; [predicted.dat] [--mask mask.txt]</span></span></code></pre></div><p>The window needs GLMakie and a display. On a cluster, <code>--png &lt;dir&gt;</code> (or <code>interactive = false, snapshot_dir = &quot;&lt;dir&gt;&quot;</code>) writes one PNG per site with CairoMakie instead.</p><h2 id="What-it-shows" tabindex="-1">What it shows <a class="header-anchor" href="#What-it-shows" aria-label="Permalink to &quot;What it shows {#What-it-shows}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Panel</th><th style="text-align:left;">Content</th></tr></thead><tbody><tr><td style="text-align:left;">Apparent resistivity</td><td style="text-align:left;">Zxy (red) and Zyx (blue), with error bars; the range fits the kept points with half a decade to spare</td></tr><tr><td style="text-align:left;">Phase</td><td style="text-align:left;">the same components as recorded, on a fixed −200° to 200°: Zxy in the first quadrant, Zyx in the third</td></tr><tr><td style="text-align:left;">Tipper</td><td style="text-align:left;">Re (red) and Im (blue) of Tzx above Tzy, on the right</td></tr><tr><td style="text-align:left;">Map</td><td style="text-align:left;">the sites in longitude and latitude (true distances), on the left; click one to go there</td></tr></tbody></table><p><strong>Full tensor</strong> adds Zxx (pale green) and Zyy (pale purple) to the same two panels; it only changes the view, and masking always takes all four impedances. The map and the tipper collapse with the buttons at the left and right edges; the tipper starts collapsed when the survey has none. With all three open the map, ρa/φ and tipper columns share the width 1 : 2 : 2; with one side closed the other two are equal. Every site shares the survey&#39;s period axis. Observed data are markers, a predicted response is lines, and masked points are hollow.</p><h2 id="Masking" tabindex="-1">Masking <a class="header-anchor" href="#Masking" aria-label="Permalink to &quot;Masking {#Masking}&quot;">​</a></h2><p>No panel zooms or pans, and masking is by drag only; a click on a data panel does nothing:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Action</th><th style="text-align:left;">Effect</th></tr></thead><tbody><tr><td style="text-align:left;">drag across ρa or φ</td><td style="text-align:left;">select a band of periods over both panels and mask all four impedances in it</td></tr><tr><td style="text-align:left;">drag across a tipper panel</td><td style="text-align:left;">mask Tzx and Tzy in the band</td></tr><tr><td style="text-align:left;">drag with Shift held</td><td style="text-align:left;">restore the band instead</td></tr><tr><td style="text-align:left;"><strong>Mask site</strong> / <strong>Restore site</strong></td><td style="text-align:left;">mask or restore the whole site</td></tr><tr><td style="text-align:left;"><strong>Save mask</strong></td><td style="text-align:left;">write the mask to <code>mask_path</code> (default: the <code>mask</code> it started from, else <code>&lt;name&gt;_mask.txt</code>)</td></tr><tr><td style="text-align:left;"><strong>Write ModEM</strong></td><td style="text-align:left;">write the kept data to <code>&lt;name&gt;_&lt;date_time&gt;.dat</code></td></tr><tr><td style="text-align:left;"><strong>Write EDI</strong></td><td style="text-align:left;">write the kept data as one EDI per site to <code>&lt;name&gt;_EDI_&lt;date_time&gt;/</code></td></tr><tr><td style="text-align:left;"><strong>Save PNG</strong></td><td style="text-align:left;">write the window as a PNG</td></tr><tr><td style="text-align:left;">← / →</td><td style="text-align:left;">previous / next site</td></tr></tbody></table><p>Both writes keep the errors as they were read; the editor applies no error floor. A new time-stamped name each time means no write replaces an earlier one.</p><p>A band on ρa or φ takes the full impedance tensor at its periods, and one on the tipper takes Re and Im of both components. Axis ranges follow the kept points, so masking an outlier zooms in on the rest; a masked point that falls outside comes back with <strong>Restore site</strong> or a restoring band.</p><h2 id="Mask-files" tabindex="-1">Mask files <a class="header-anchor" href="#Mask-files" aria-label="Permalink to &quot;Mask files {#Mask-files}&quot;">​</a></h2><p>A mask file lists what is left out, one line per site, period and component. <code>*</code> stands for every period or every component:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># MTGeophysics data mask, 2026-09-29 14:02:11, from Quantec2017.dat</span></span>
<span class="line"><span># one masked datum per line; * is every period or every component; components Zxx Zxy Zyx Zyy Tzx Tzy</span></span>
<span class="line"><span># zrot 0.00</span></span>
<span class="line"><span># site  period_s  component</span></span>
<span class="line"><span>MT1247  8.192021e-02  *</span></span>
<span class="line"><span>MT1247  2.925700e+01  Zxy</span></span>
<span class="line"><span>MT1250  *  *</span></span></code></pre></div><p>Apply it to the survey in either form; the originals are not touched:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">apply_data_mask</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data.dat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data_mask.txt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># -&gt; data_masked_&lt;date_time&gt;.dat</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">apply_data_mask</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;EDI/&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data_mask.txt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># -&gt; EDI_masked_&lt;date_time&gt;/ and EDI_masked_&lt;date_time&gt;.dat</span></span></code></pre></div><p>For a ModEM file the masked lines are dropped and everything else is kept as written. EDIs are read as <code>EDIToModEM</code> reads them, written again without the masked values (fully masked sites are left out), and converted to the ModEM file beside them. Sites match by name and periods within 1 % (<code>rtol</code>). The mask records the frame it was drawn in (<code>zrot</code>), and applying it to data in another frame gives a warning, since Zxy in one frame is not Zxy in another. In code, <code>apply_data_mask!(d, mask)</code> masks a <code>Data</code> in place and <code>mask_keep(d, mask)</code> returns what a mask keeps.</p><h2 id="Options" tabindex="-1">Options <a class="header-anchor" href="#Options" aria-label="Permalink to &quot;Options {#Options}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">DataDashboard</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data.dat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    predicted </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;dpred.dat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    mask </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;data_mask.txt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, mask_path </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;data_mask.txt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    show_map </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, show_tipper </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> nothing</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,           </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># side panels at start; nothing: open if there is a tipper</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    full_tensor </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    export_dir </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;exports&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)                           </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># where Write ModEM / Write EDI go (default: beside the data)</span></span></code></pre></div><p>A response from a rotated mesh is turned back into the frame of the observed data before it is compared. Sites are matched by name, periods within 2 %.</p>`,26)])])}const c=s(n,[["render",l]]);export{g as __pageData,c as default};
